 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid, uniform outer row or column marks the side toward which objects settle.
    wall = None
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            wall = ("row", r, row[0])
            break
    if wall is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if vals[0] != 0 and all(v == vals[0] for v in vals):
                wall = ("col", c, vals[0])
                break
    if wall is None:
        return [row[:] for row in grid]

    axis, wall_idx, wall_color = wall
    occupied = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall_color:
                occupied[r][c] = True

    # Extract 4-connected monochromatic objects, excluding the wall color.
    seen = [[False] * w for _ in range(h)]
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == wall_color or seen[r][c]:
                continue
            cells = []
            stack = [(r, c)]
            seen[r][c] = True
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            objects.append((color, cells))

    if axis == "row":
        # Downward gravity if the wall is at the bottom; upward if at the top.
        direction = 1 if wall_idx == h - 1 else -1
        objects.sort(key=lambda obj: (max(y for y, x in obj[1]) if direction == 1 else -min(y for y, x in obj[1])))
        boundary = wall_idx
    else:
        direction = 1 if wall_idx == w - 1 else -1
        objects.sort(key=lambda obj: (max(x for y, x in obj[1]) if direction == 1 else -min(x for y, x in obj[1])))
        boundary = wall_idx

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall_color:
                out[r][c] = wall_color

    # Settle nearer objects first, preserving each object's shape and orientation.
    for color, cells in objects:
        dr = dc = 0
        while True:
            nr, nc = (direction, 0) if axis == "row" else (0, direction)
            moved = [(y + dr + nr, x + dc + nc) for y, x in cells]
            if any(y < 0 or y >= h or x < 0 or x >= w for y, x in moved):
                break
            if any(out[y][x] != 0 for y, x in moved):
                break
            dr += nr
            dc += nc
        for y, x in cells:
            out[y + dr][x + dc] = color
    return out
